import sys
from collections import Counter

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def can_rearrange(s):
    n = len(s)
    freq = Counter(s)
    for p in range(2, n + 1):
        if is_prime(p) and n % p != 0:
            continue
        block_size = n // p
        for char in freq:
            if freq[char] % block_size != 0:
                return False
    return True

def construct_string(s):
    n = len(s)
    freq = Counter(s)
    result = []
    for _ in range(n):
        for char in sorted(freq):
            if freq[char] > 0:
                result.append(char)
                freq[char] -= 1
                break
    return ''.join(result)

def main():
    import sys
    s = sys.stdin.read().strip()
    if can_rearrange(s):
        print("YES")
        print(construct_string(s))
    else:
        print("NO")

if __name__ == "__main__":
    main()
